const raw = $input.first().json.choices?.[0]?.message?.content ?? $input.first().json.sql ?? '';
const sql = String(raw).replace(/```sql/gi, '').replace(/```/g, '').trim();
const forbidden = /\b(DROP|DELETE|UPDATE|INSERT|ALTER|TRUNCATE|CREATE|GRANT|REVOKE|EXECUTE)\b/i;
const ctx = $('Load Schema').first().json;
const retryCtx = $('Prepare SQL Retry').isExecuted ? $('Prepare SQL Retry').first().json : null;

if (!sql) {
  throw new Error('Groq không trả về SQL.');
}
if (forbidden.test(sql)) {
  throw new Error('Chỉ cho phép truy vấn SELECT. Phát hiện lệnh bị cấm.');
}
if (!/^\s*SELECT\b/i.test(sql)) {
  throw new Error('Chỉ cho phép truy vấn SELECT.');
}

return {
  sql,
  query: retryCtx?.query ?? ctx.query,
  schemaText: ctx.schemaText,
  retryCount: retryCtx?.retryCount ?? 0
};

const errItem = $input.first().json;
const validated = $('Validate SQL').first().json;
const loadSchema = $('Load Schema').first().json;
const retryCount = (validated.retryCount ?? 0) + 1;

if (retryCount > 2) {
  throw new Error('SQL vẫn lỗi sau 2 lần sửa: ' + (errItem.error?.message ?? errItem.message ?? JSON.stringify(errItem)));
}

const pgError = errItem.error?.message ?? errItem.message ?? 'Unknown PostgreSQL error';

return {
  query: validated.query ?? loadSchema.query,
  sql: validated.sql,
  schemaText: loadSchema.schemaText,
  retryCount,
  pgError
};

