const items = $input.all().map(i => i.json);
const query = $('Validate SQL').first().json.query;
const sql = $('Validate SQL').first().json.sql;

if (!items.length || items[0].error) {
  return {
    query,
    sql,
    markdown: 'Không có kết quả.',
    summary: 'Truy vấn không trả về dòng dữ liệu nào.'
  };
}

const keys = Object.keys(items[0]);
const header = '| ' + keys.join(' | ') + ' |';
const sep = '| ' + keys.map(() => '---').join(' | ') + ' |';
const rows = items.map(row => '| ' + keys.map(k => String(row[k] ?? '')).join(' | ') + ' |');
const markdown = [header, sep, ...rows].join('\n');

return {
  query,
  sql,
  rowCount: items.length,
  markdown,
  summary: `Tìm thấy ${items.length} dòng kết quả cho câu hỏi: ${query}`
};
